<?php require_once "../config/database.php";require_once "../config/auth.php";require_role('admin');$rows=$conn->query("SELECT f.*,r.name restaurant_name FROM foods f JOIN restaurants r ON r.id=f.restaurant_id ORDER BY f.id DESC");?><!doctype html><html lang="vi"><head><meta charset="utf-8"><title>Món ăn</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1>Quản lý món ăn</h1><table class="table"><tr><th>ID</th><th>Món</th><th>Nhà hàng</th><th>Giá</th><th>Trạng thái</th></tr><?php while($f=$rows->fetch_assoc()):?><tr><td><?=$f['id']?></td><td><?=htmlspecialchars($f['name'])?></td><td><?=htmlspecialchars($f['restaurant_name'])?></td><td><?=money($f['price'])?></td><td><?=$f['status']?></td></tr><?php endwhile;?></table><p><a class="btn secondary" href="index.php">← Admin</a></p></main></body></html>